-- Adds the mechanics object used by evaluateSynergies.
-- Import this once. It does not delete accounts, favorites, or squads.
-- Numbers stored here are unmodded max-rank values.

USE frame_codex;

ALTER TABLE warframes ADD COLUMN mechanics JSON NULL;

UPDATE warframes SET mechanics = '{"buffs_provided":[{"tag":"invisibility_self","ability":"Smoke Screen","target":"self","summary":"Ash turns invisible for a short time. Only his melee can land stealth hits. Allies stay visible."}],"sustain_provided":[],"ability_tags":["invisibility_self"]}' WHERE slug = 'ash';
UPDATE warframes SET mechanics = '{"buffs_provided":[{"tag":"invisibility_self","ability":"Invisibility","target":"self","summary":"Loki cloaks himself. The stealth melee multiplier applies to Loki only."}],"sustain_provided":[],"ability_tags":["invisibility_self"]}' WHERE slug = 'loki';
UPDATE warframes SET mechanics = '{"buffs_provided":[{"tag":"invisibility_self","ability":"Prowl","target":"self","summary":"Ivara goes invisible while Prowl is active. Only she gets the stealth melee multiplier from it."},{"tag":"invisibility_squad","ability":"Quiver","target":"squad","summary":"The cloak arrow hides allies who stand in its bubble, so their melee can use the stealth multiplier too.","condition":"Allies have to stay inside the cloak bubble."}],"sustain_provided":[],"ability_tags":["invisibility_self","invisibility_squad"]}' WHERE slug = 'ivara';
UPDATE warframes SET mechanics = '{"buffs_provided":[{"tag":"invisibility_squad","ability":"Metronome","target":"squad","summary":"Allies who match the crouch action become invisible, and their melee can score stealth hits while that buff holds.","condition":"The ally must crouch in time with the beat."}],"sustain_provided":[],"ability_tags":["invisibility_squad"]}' WHERE slug = 'octavia';
UPDATE warframes SET mechanics = '{"buffs_provided":[{"tag":"invisibility_self","ability":"Shroud of Dynar","target":"self","summary":"Voruna turns invisible, then her next melee is stronger. The cloak and the melee bonus are hers alone."}],"sustain_provided":[],"ability_tags":["invisibility_self"]}' WHERE slug = 'voruna';
UPDATE warframes SET mechanics = '{"buffs_provided":[{"tag":"invisibility_self","ability":"Evade","target":"self","summary":"Cyte-09 turns invisible. The stealth multiplier applies to his own attacks, not the squad."}],"sustain_provided":[],"ability_tags":["invisibility_self"]}' WHERE slug = 'cyte-09';
UPDATE warframes SET mechanics = '{"buffs_provided":[],"sustain_provided":[{"tag":"energy_pulse","ability":"Energy Vampire","target":"squad","summary":"A marked enemy must stay in range. If it dies, the remaining pulses are released at once. One enemy can be marked at a time.","energy_cost":50,"energy_per_pulse":25,"duration_seconds":9,"pulse_interval_seconds":2.25,"radius_meters":25},{"tag":"shield_restore","ability":"Blessing","target":"squad","summary":"Restores shields for Trinity and nearby allies, which lets a spent shield gate recover."},{"tag":"squad_heal","ability":"Blessing","target":"squad","summary":"Restores health for the squad and grants damage reduction for a short time."},{"tag":"squad_heal","ability":"Well of Life","target":"squad","summary":"A marked enemy becomes a healing source for allies who damage it."}],"ability_tags":["energy_pulse","shield_restore","squad_heal"]}' WHERE slug = 'trinity';
UPDATE warframes SET mechanics = '{"buffs_provided":[],"sustain_provided":[{"tag":"energy_multiplier","ability":"Nourish","target":"squad","summary":"At max rank with no strength mods, energy from pickups and abilities is doubled while the buff lasts. He must have an enemy stored to cast it.","multiplier":2,"duration_seconds":25}],"ability_tags":["energy_multiplier"]}' WHERE slug = 'grendel';
UPDATE warframes SET mechanics = '{"buffs_provided":[],"sustain_provided":[{"tag":"energy_regen","ability":"Cathode Grace","target":"self","summary":"The buff starts at 8 seconds and gains 3 seconds per qualifying kill, up to 60 seconds. Casting another ability pauses this regen for 1 second. Allies do not receive it.","energy_per_second":1.5,"energy_cost":75}],"ability_tags":["energy_regen"]}' WHERE slug = 'gyre';
UPDATE warframes SET mechanics = '{"buffs_provided":[],"sustain_provided":[{"tag":"energy_on_kill","ability":"Thurible","target":"squad","summary":"Channel energy into Thurible first. After that, each kill grants energy to nearby allies, and headshots pay more. There is no energy per second until something dies."},{"tag":"shield_restore","ability":"Condemn","target":"self","summary":"Each chained enemy adds shields to Harrow, so his own shield gate can reset. Allies do not gain those shields."}],"ability_tags":["energy_on_kill","shield_restore"]}' WHERE slug = 'harrow';
UPDATE warframes SET mechanics = '{"buffs_provided":[],"sustain_provided":[{"tag":"energy_orb","ability":"Dispensary","target":"squad","summary":"The station drops energy orbs for anyone nearby. Gain depends on how often an orb is picked up, not on a constant rate.","energy_per_orb":25},{"tag":"health_orb","ability":"Dispensary","target":"squad","summary":"The same station drops health orbs, so the squad can heal from pickups while it is deployed."},{"tag":"shield_restore","ability":"Grenade Fan","target":"self","summary":"The shield grenade refills Protea''s shields after they break, which prepares her next shield gate. It does not refill the rest of the squad."}],"ability_tags":["energy_orb","health_orb","shield_restore"]}' WHERE slug = 'protea';
UPDATE warframes SET mechanics = '{"buffs_provided":[],"sustain_provided":[{"tag":"bonus_orbs","ability":"Desecrate","target":"squad","summary":"Corpses can drop extra health orbs and energy orbs. An unmodified energy orb restores 25 energy.","energy_per_orb":25}],"ability_tags":["bonus_orbs"]}' WHERE slug = 'nekros';
UPDATE warframes SET mechanics = '{"buffs_provided":[],"sustain_provided":[{"tag":"orb_chance","ability":"Fractured Blast","target":"squad","summary":"Enemies hit by the blast are more likely to drop health orbs and energy orbs."},{"tag":"health_regen","ability":"Gem Heart","target":"squad","summary":"Nearby allies regenerate health. Picking up health orbs raises that regeneration, so extra orbs from other frames make the heal stronger."}],"ability_tags":["orb_chance","health_regen"]}' WHERE slug = 'citrine';
UPDATE warframes SET mechanics = '{"buffs_provided":[],"sustain_provided":[{"tag":"health_orb_to_energy","ability":"Equilibrium","target":"self","summary":"In day form, a health orb also gives Equinox energy. Orb makers in the squad feed her energy. Allies do not get this conversion."},{"tag":"squad_heal","ability":"Mend & Maim","target":"squad","summary":"Night form stores damage taken nearby and can release it as a heal. The heal only exists after damage has been stored."}],"ability_tags":["health_orb_to_energy","squad_heal"]}' WHERE slug = 'equinox';
UPDATE warframes SET mechanics = '{"buffs_provided":[],"sustain_provided":[{"tag":"health_regen","ability":"Reservoirs","target":"squad","summary":"The vitality mote regenerates health for Wisp and allies who use the reservoir."}],"ability_tags":["health_regen"]}' WHERE slug = 'wisp';
UPDATE warframes SET mechanics = '{"buffs_provided":[],"sustain_provided":[{"tag":"squad_heal","ability":"Renewal","target":"squad","summary":"Heals allies over time. The heal is stronger while they stand in Hallowed Ground."}],"ability_tags":["squad_heal"]}' WHERE slug = 'oberon';
UPDATE warframes SET mechanics = '{"buffs_provided":[],"sustain_provided":[{"tag":"shield_restore","ability":"Pillage","target":"self","summary":"Steals shields and armor from enemies and adds them to Hildryn. That refill lets her shield gate trigger again. Allies are not refilled."}],"ability_tags":["shield_restore"]}' WHERE slug = 'hildryn';
UPDATE warframes SET mechanics = '{"buffs_provided":[],"sustain_provided":[{"tag":"shield_restore","ability":"Polarize","target":"squad","summary":"Restores shields for Mag and nearby allies while stripping enemy shields and armor."}],"ability_tags":["shield_restore"]}' WHERE slug = 'mag';
UPDATE warframes SET mechanics = '{"buffs_provided":[],"sustain_provided":[{"tag":"shield_restore","ability":"Rally Point","target":"squad","summary":"Allies restore shields when they deal damage under the banner. Shields come back only while the squad is getting hits."}],"ability_tags":["shield_restore"]}' WHERE slug = 'styanax';
UPDATE warframes SET mechanics = '{"buffs_provided":[],"sustain_provided":[{"tag":"shield_recharge","ability":"Shield Link","target":"squad","summary":"Caliban and nearby allies recharge shields faster, so a broken shield gate can be set up again sooner."}],"ability_tags":["shield_recharge"]}' WHERE slug = 'caliban';
UPDATE warframes SET mechanics = '{"buffs_provided":[],"sustain_provided":[{"tag":"health_to_energy","ability":"Bloodletting","target":"self","summary":"Garuda spends health to restore a burst of her own energy. Allies do not receive that energy."},{"tag":"squad_heal","ability":"Blood Altar","target":"squad","summary":"An impaled enemy heals Garuda and nearby allies for as long as the altar lasts."}],"ability_tags":["health_to_energy","squad_heal"]}' WHERE slug = 'garuda';
UPDATE warframes SET mechanics = '{"buffs_provided":[],"sustain_provided":[{"tag":"damage_to_energy","ability":"Kinetic Plating","target":"self","summary":"Part of the kinetic damage Gauss takes becomes energy. This loop is personal and does not fill the squad."}],"ability_tags":["damage_to_energy"]}' WHERE slug = 'gauss';
UPDATE warframes SET mechanics = '{"buffs_provided":[],"sustain_provided":[{"tag":"universal_orb","ability":"Transmutation Probe","target":"squad","summary":"Turns health and energy orbs into universal orbs that restore both. The squad gets health and energy from the same pickup. Lavos himself does not spend energy."}],"ability_tags":["universal_orb"]}' WHERE slug = 'lavos';

-- Primes and Protoframes use the linked Warframe kit, so they share its mechanics.
UPDATE warframes AS child
INNER JOIN warframes AS parent ON parent.id = child.related_id
SET child.mechanics = parent.mechanics
WHERE child.category IN ('prime', 'protoframe')
  AND parent.mechanics IS NOT NULL;
